IN.relics = [{"id":"bread","s":"seam","x":21,"y":7,"name":"a heel of bread","text":"Cosmi used to pass it to her at the campfires. Nobody else sat that close.","story":"inc-first-war"},{"id":"sharpie","s":"kitchen","x":3,"y":6,"name":"a dead Sharpie","text":"One of eleven.","story":"inc-statue"},{"id":"tin","s":"laundry","x":13,"y":6,"name":"a mint tin","text":"Behind the washer. It rattles. Corruption shards, in blue and gold. You put it back very carefully.","story":"inc-relapse"},{"id":"chalk","s":"under","x":2,"y":7,"name":"a stub of chalk","text":"A note in a girl's handwriting: THE BARN. TANNER BARN. YOU WERE THERE. YOU WON.","story":"inc-chalk"},{"id":"orange","s":"broken","x":47,"y":12,"name":"a bag of oranges","text":"For a monthly visit, down the canyon path. One's been peeled and left.","story":"inc-ember"},{"id":"frog","s":"broken","x":58,"y":44,"name":"a lunchbox with a frog on it","text":"The smallest, shyest girl in the room had this on the first day of school. “You want to sit with me, don't you?”","story":"inc-leash"},{"id":"cards","s":"school","x":16,"y":8,"name":"a tarot card","text":"The Tower, scorched at one corner. A dollar's worth of being right.","story":"inc-wall-of-string"},{"id":"notebook","s":"nursery","x":21,"y":12,"name":"a brown notebook page","text":"LOG 0. Note: Do not get attached. The ink has gone the colour of dried blood.","story":"inc-plan-b"},{"id":"copy","s":"hermitage","x":2,"y":7,"name":"a copied page","text":"Word for word, letter for letter, in the hand of a man who loved his job more than anything in the world.","story":"inc-hermitage"},{"id":"static_tape","s":"radiotower","x":12,"y":6,"name":"a cassette of 98.4 FM","text":"Thirty minutes of static, then someone humming.","story":"inc-static"},{"id":"last_slice","s":"pizzeria","x":9,"y":6,"name":"a cold pizza box","text":"Left on table four. Nobody came back.","story":"inc-last-slice"},{"id":"encore_ticket","s":"theater","x":13,"y":6,"name":"an encore stub","text":"Row A, Seat 1. Stamped FOREVER.","story":"inc-encore"},{"id":"mermaid_scale","s":"pier","x":10,"y":6,"name":"a silver scale","text":"Left on the wet planks at the end of the pier.","story":"inc-mermaid"},{"id":"conquest_arrow","s":"conquest_hall","x":12,"y":6,"name":"a snapped white arrow","text":"It never misses, unless you refuse to stand still.","story":"inc-conquest"},{"id":"pale_bridle","s":"pale_corridor","x":14,"y":6,"name":"a silver bridle","text":"Cold as frost, light as ash.","story":"inc-conquest"},{"id":"pancake_tin","s":"salt_pantry","x":10,"y":7,"name":"a tin of Sunday batter","text":"Still smells faintly of vanilla and burned edges.","story":"inc-plan-b"},{"id":"draft_ink","s":"unmarked_door","x":12,"y":7,"name":"an unopened bottle of white ink","text":"For erasing a prophecy before anyone reads it.","story":"inc-hermitage"},{"id":"mini_portal_shard","s":"portal_lab","x":15,"y":5,"name":"a shimmering aurora-fluid vial","text":"Taken from the lab with the mini-portal where Ena's seizures began.","story":"inc-b1a1"},{"id":"torn_prom","s":"portal_lab","x":5,"y":8,"name":"a torn prom dress ribbon","text":"Left on the metal table in the center of the arcane diagrams.","story":"inc-b1a1"},{"id":"iv_aurora","s":"hospital_b1","x":13,"y":6,"name":"an empty aurora-fluid IV bag","text":"Purple bruising and whispered warnings.","story":"inc-b1a1"},{"id":"heart_monitor","s":"hospital_ward","x":7,"y":6,"name":"a fading heart-monitor strip","text":"Rhythmic beeps echoing the Siren Song.","story":"inc-b1a1"},{"id":"cafe_tray","s":"school_cafe","x":14,"y":6,"name":"an overturned cafeteria tray","text":"Halcyon High, before the song reached the hallways.","story":"inc-b1a1"},{"id":"red_plaque","s":"kitchen","x":9,"y":6,"name":"a shard of red plaque","text":"Fell during Ena's first seizure on a Tuesday.","story":"inc-b1a1"},{"id":"drake_ration","s":"drake_camp","x":15,"y":4,"name":"an empty ration tin","text":"Food is now an essential luxury.","story":"inc-hunger"},{"id":"owen_proof","s":"ruined_city","x":14,"y":5,"name":"a proofreader's red pencil","text":"Marked in the margin by Brian, Rui, and Owen.","story":"inc-b1a1"},{"id":"hemp_ledger","s":"pelagia","x":7,"y":3,"name":"a hemp-bound salt ledger","text":"Four handwritings share the pages: Ena's careful script, Harumi's sharp slant, Kio's block knot-counts, and Sunny's chalk drawing of an orange cat with half an ear.","story":"inc-b2"},{"id":"whalebone_splint","s":"drift_weir","x":11,"y":8,"name":"a spare whalebone shin-splint","text":"Carved by Wren for Eri's broken legs, worn smooth by salt water and kelp poultices.","story":"inc-b2"},{"id":"clapperless_bell","s":"cliff_oranges","x":13,"y":8,"name":"a clapperless silver bell","text":"Mark tore the clapper out so it only rings when the sea wind knocks it against the stilt-house door.","story":"inc-b2"},{"id":"jar_b2","s":"glass_shoals","x":16,"y":8,"name":"an empty salt-rimmed jar","text":"Left on the flooded cellar step in the Glass Shoals lighthouse. It smells faintly of river water and old songs.","story":"inc-b2"},{"id":"paper_crown_b2","s":"leviathan_ribs","x":14,"y":7,"name":"a yellow paper crown","text":"Drawn with purple crayon stars by a nine-year-old who stood up and asked Conquest why.","story":"inc-b2"},{"id":"cold_chisel","s":"bridge_names","x":3,"y":7,"name":"a cold chisel","text":"For the unfinished names of the eastern front. The handle is worn to the shape of one hand, ten thousand years old.","story":"inc-first-war"},{"id":"salt_glass","s":"salt_chapel","x":17,"y":5,"name":"a pane of salt glass","text":"Laid over the altar page. Under it, in a hand corrupted for one second and sorry forever: Please don't hurt her.","story":"inc-prophecy"},{"id":"meridian_compass","s":"sunken_meridian","x":12,"y":8,"name":"a salt-fogged meridian compass","text":"Points toward the Leviathan Ribs no matter how far west the tide pulls.","story":"inc-b2"},{"id":"blue_button_shard","s":"blue_tin_vault","x":14,"y":6,"name":"a numbered blue button","text":"Stamped 09 from Marguerite's tin. Still cold from the laundromat floor.","story":"inc-sponsor"},{"id":"ash_chime_bell","s":"ash_chime_quay","x":6,"y":6,"name":"a clapperless ash-chime","text":"Hung on the quay pilings to warn boats off the trench.","story":"inc-b2"},{"id":"chalk_cat_tile","s":"ash_chime_quay","x":14,"y":7,"name":"a chalk-drawn orange cat","text":"Tim with half an ear, drawn by Sunny on a loose cedar plank.","story":"inc-b2"},{"id":"kaina_shell_casing","s":"eastern_front_archive","x":15,"y":4,"name":"a ten-thousand-year shell casing","text":"From one small shot fired at the end of everything.","story":"inc-first-war"},{"id":"blank_seventh_page","s":"seventh_ledger_room","x":14,"y":6,"name":"a blank seventh ledger page","text":"Unwritten, uncorrupted, and dry by the fire.","story":"inc-margin-notes"}];
